import {APCM_CODES,CODES,YEARS,DATA_VERSION,ENGINE_VERSION,defaultState,validate,eventsFor,modifierFor,changeBreakdown} from './engine.mjs';
import {DATA_SHA256} from './data/provenance.mjs';
export const defaultView=()=>({years:[2027,2026,2001,1992],chart:{from:1992,to:2027}});
export const validChart=c=>!!c&&Object.keys(c).length===2&&Number.isInteger(c.from)&&Number.isInteger(c.to)&&YEARS.includes(c.from)&&YEARS.includes(c.to)&&c.from<c.to;
export const validYears=v=>v&&Object.keys(v).every(k=>['years','chart'].includes(k))&&(!('chart' in v)||validChart(v.chart))&&Array.isArray(v.years)&&[2,3,4].includes(v.years.length)&&v.years.every(y=>Number.isInteger(y)&&YEARS.includes(y))&&new Set(v.years).size===v.years.length;
export function monthlySeries(result,base=2027){if(!result.valid)throw Error('Invalid practice inputs');const end=result.years.find(y=>y.year===base);if(!end)throw Error('Unknown base year');return result.years.map(y=>({year:y.year,nominal:y.nominalMonthly,CPI:y.nominalMonthly*end.indices.CPI.factor/y.indices.CPI.factor,MEI:y.nominalMonthly*end.indices.MEI.factor/y.indices.MEI.factor,cf:y.cf}));}
export const descendingYears=years=>[...years].sort((a,b)=>b-a);
export function comparisonYears(years){const all=[...years];for(const y of defaultView().years){if(all.length===4)break;if(!all.includes(y))all.push(y);}return descendingYears(all);}
export const serialize=(state,view)=>encodeURIComponent(JSON.stringify({version:DATA_VERSION,state,view:{years:comparisonYears(view.years),chart:validChart(view.chart)?view.chart:defaultView().chart}}));
// Older links stored a single `profile` (nonqp = non-QP + B1; qp = QP + ACO + B2, the published main-branch format),
// or the interim qp/aco checkboxes. Map both to the track answers that price the same way (MSSP track unknown: BASIC A–D).
function migrateState(s){if(!s||typeof s!=='object')return s;if(!('apcm' in s))s={...s,apcm:{G0556:0,G0557:0,G0558:0}};let {profile,inflation,aco,...rest}=s;
 if(profile!==undefined){if(!['nonqp','qp'].includes(profile))return null;aco=profile==='qp';rest.qp=aco;}
 else if(aco===undefined)return s;
 if(typeof aco!=='boolean'||typeof rest.qp!=='boolean')return null;
 return {...rest,program:aco?'aco':rest.qp?'apm':'none',track:aco?'basic-ad':null};}
export function restore(value){try{const r=JSON.parse(decodeURIComponent(value));if(r.version!==DATA_VERSION)return {error:'This saved comparison uses unavailable data. Choose current defaults to continue.'};const s=migrateState(r.state);const keys=Object.keys(defaultState());if(!s||Object.keys(s).some(k=>!keys.includes(k))||keys.some(k=>!(k in s))||!s.mix||Object.keys(s.mix).length!==CODES.length||Object.keys(s.mix).some(k=>!CODES.includes(k))||validate(s).length)return {error:'These saved practice settings are invalid. Choose current defaults to continue.'};let v=r.view;if(!v||Object.keys(v).length===1&&YEARS.includes(v.year))v=defaultView();else if(Object.keys(v).every(k=>['from','to','benchmark','inspect'].includes(k))&&Number.isInteger(v.from)&&Number.isInteger(v.to)&&YEARS.includes(v.from)&&YEARS.includes(v.to)&&v.from<v.to&&['CPI','MEI'].includes(v.benchmark)&&YEARS.includes(v.inspect)){v={years:[v.from,v.to]};}if(!validYears(v))return {error:'Choose two to four distinct years between 1992 and 2027.'};return {state:s,view:{years:comparisonYears(v.years),chart:v.chart??defaultView().chart}};}catch{return {error:'This saved comparison could not be opened.'};}}
// Policy events by category: rate = conversion factor; rvu = RVU values; coding = complexity coding.
export const EVENT_CATEGORIES={rate:'Payment rate',rvu:'RVU values',coding:'Coding changes'};
// parts: which pieces of yearBreakdown() this event represents (its "This change" amount).
const EVENTS=[
 {year:1997,category:'rvu',parts:['revaluation'],label:'Work RVU update',detail:'Office visit work RVUs rose, offset by a 0.917 work adjustment.'},
 {year:1999,category:'rvu',parts:['revaluation'],label:'Practice-expense transition',detail:'Practice-expense RVUs began moving from historical charges to resource costs.'},
 {year:2007,category:'rvu',parts:['revaluation'],label:'Office RVU update',detail:'Work RVUs for established visits rose, offset by a 0.8994 work adjustment.'},
 {year:2009,category:'rate',parts:['conversionFactor','revaluation'],label:'Work adjustment into CF',detail:'The 0.8806 work adjustment left the RVUs and was folded into a lower conversion factor.',policy:'2009-rate'},
 {year:2013,category:'rate',parts:['sequestration'],label:'2% sequestration begins',detail:'From April 1, Medicare’s payment is cut 2%: about 1.6% of the allowed amount.',policy:'2013-sequestration'},
 {year:2015,category:'rate',parts:['conversionFactor'],label:'SGR repealed',detail:'MACRA replaced the SGR formula and its scheduled 21% cut; +0.5% from July 1.',policy:'2015-rate'},
 {year:2020,category:'rate',parts:['sequestration'],label:'Sequestration paused',detail:'Suspended from May 1, 2020, during COVID-19, through March 2022.',policy:'2020-sequestration'},
 {year:2021,category:'rvu',parts:['revaluation'],label:'Office E/M revaluation',detail:'Office visit RVUs rose substantially; visit levels by decision-making or time.'},
 {year:2021,category:'rate',parts:['conversionFactor'],label:'CF cut for budget neutrality',detail:'The conversion factor fell 3.3%, after a one-year 3.75% increase from Congress.',policy:'2021-rate'},
 {year:2022,category:'rate',parts:['sequestration'],label:'Sequestration returns',detail:'1% from April 1 and the full 2% from July 1, 2022.',policy:'2022-sequestration'},
 {year:2024,category:'coding',parts:['coding'],label:'G2211 added',detail:'G2211 became payable as a fixed add-on to office visits.'},
 {year:2025,category:'coding',parts:['apcm'],label:'APCM codes added',detail:'Monthly Advanced Primary Care Management codes G0556–G0558 begin.',policy:'2025-apcm',apcm:true},
 {year:2025,category:'rate',parts:['conversionFactor'],label:'CF cut, 4th year',detail:'The conversion factor fell every year from 2022 to 2025.'},
 {year:2026,category:'rate',parts:['conversionFactor','revaluation'],label:'CF and office PE up',detail:'A one-year 2.5% increase, and higher office practice-expense RVUs.'},
 {year:2027,category:'rvu',parts:['revaluation'],label:'Office PE RVUs down',detail:'Practice-expense RVUs for office visits fall; work RVUs are unchanged.',policy:'2027-rvu'},
 {year:2027,category:'rate',parts:['conversionFactor'],label:'2026 bonus expires',detail:'The one-year 2.5% increase ends; the 2027 update is +0.25% non-QP, +0.75% QP.',policy:'2027-rate'},
 {year:2027,category:'coding',parts:['coding'],label:'B1 / B2 added',detail:'B1 (16%) or B2 (32%) of the visit’s full fee replaces the fixed G2211 add-on.'}];
export function significantEvents(data,state){const valuations=eventsFor(data,state);return EVENTS.filter(e=>e.apcm?APCM_CODES.some(c=>state.apcm[c]>0):e.category==='coding'?state.complexity>0&&CODES.some(c=>state.mix[c]>0):e.category==='rate'||e.year===1999||valuations.some(v=>v.year===e.year&&v.type==='valuation')).map(e=>{const v=valuations.find(v=>v.year===e.year&&v.type==='valuation');const increased=v?.changes.filter(c=>c.current.work>c.old.work);return {...e,id:`${e.year}-${e.category}`,policy:e.policy??e.year,label:e.year===2027&&e.category==='coding'?`${modifierFor(state)} replaces G2211`:[1997,2007].includes(e.year)&&increased?.length?'Work RVUs increased':e.label,changes:v?.changes||[]};});}
export function monthlyCSV(data,state,result,view){if(!validYears(view)||!result.valid)throw Error('Invalid comparison');const points=monthlySeries(result),b=changeBreakdown(data,state);const rows=[['Medicare Payment Explorer','Monthly payments'],['Data version',DATA_VERSION],['Engine version',ENGINE_VERSION],['Data SHA256',DATA_SHA256],['2027 calculation','B1 = 16% / B2 = 32% of the base E/M total RVUs (full visit fee), per the CY2027 PFS final rule'],['Inflation currency','Constant 2027 dollars'],['Scenario JSON',JSON.stringify({state,view})],['2027 participation',{none:'No APM',aco:'MSSP ACO or LEAD',apm:'Other Advanced APM'}[state.program]],['2027 MSSP/LEAD track',state.track??''],['QP in 2024 and 2025 (sets 2026 and 2027 conversion factors; assumed the same)',state.qp?'Yes':'No'],['2027 complexity modifier',modifierFor(state)],['FFS visits per day (volume input)',state.visits],['Working days per month',state.days],['Complexity share of office visits (%)',state.complexity],...APCM_CODES.map(c=>[`APCM ${c} patients per month (2025+)`,state.apcm[c]]),['Scope','National allowed amounts including the 20% patient share, after Medicare sequestration (2% of Medicare’s 80% share; day-weighted in 2013, 2020 and 2022); before collections'],['CPI','BLS annual average through 2025; CBO February 2026 forecast extension for 2026–27'],['MEI','CMS published annual update chain including productivity; not realized practice-cost inflation'],[],['2026 to 2027','Monthly (year dollars)'],['2026 total',b.from.nominalMonthly],['2027 total',b.to.nominalMonthly],['Change',b.total],['Change (%)',b.totalPct===null?'':b.totalPct*100],['2026 one-time 2.5% increase expires',b.parts.oneYearIncreaseExpires],['2027 conversion factor update and budget neutrality',b.parts.cfUpdate],['RVU revaluation',b.parts.revaluation],[`G2211 to ${b.modifier}`,b.parts.coding],['APCM rate change',b.parts.apcm],['Sequestration rate change',b.parts.sequestration],['Change after CPI (%)',b.inflation.CPI.pct===null?'':b.inflation.CPI.pct*100],['Change after MEI (%)',b.inflation.MEI.pct===null?'':b.inflation.MEI.pct*100],[],['Selected year','Nominal monthly (year dollars)','CPI-adjusted monthly (2027 dollars)','MEI-adjusted monthly (2027 dollars)','CF (year dollars/RVU)'],...comparisonYears(view.years).map(year=>{const p=points.find(p=>p.year===year);return [p.year,p.nominal,p.CPI,p.MEI,p.cf];}),[],['All years','Nominal monthly (year dollars)','CPI-adjusted monthly (2027 dollars)','MEI-adjusted monthly (2027 dollars)','CF (year dollars/RVU)','CPI factor (1992=1)','CPI status','MEI factor (1992=1)','MEI status','Allowed monthly before sequestration (year dollars)','Sequestration rate on Medicare share (%)','APCM monthly after sequestration (year dollars)']];for(const p of points){const y=result.years.find(y=>y.year===p.year);rows.push([p.year,p.nominal,p.CPI,p.MEI,p.cf,y.indices.CPI.factor,y.indices.CPI.status,y.indices.MEI.factor,y.indices.MEI.status,y.grossMonthly,y.sequestration*100,y.apcmMonthly]);}rows.push([],['Code','Visit share (%)'],...CODES.map(c=>[c,state.mix[c]]),[],['Source ID','URL','SHA256','Hash scope']);for(const s of data.sources)rows.push([s.id,s.url,s.sha256,s.hash_scope]);return '﻿'+rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');}
